import re, json, html as htmllib, pickle

def clean(s):
    if s is None: return None
    s = re.sub(r'<[^>]+>', '', s)
    s = htmllib.unescape(s)
    return re.sub(r'\s+', ' ', s).strip()

slugs = "ago ashi bikyaku ganseihiro gikkurigoshi hiza hizi katakori kenshoen kogao kokansetsu koshi-hernia kotsuban kubi-hernia kubi makigata massaji muchiuchi mukumi nancho nekoze okyaku sangokotsuban seitai sorigoshi youtuu zakotsu zutsu".split()

def extract_types_and_breadcrumb(h):
    jsonlds = re.findall(r'<script[^>]+type=["\']application/ld\+json["\'][^>]*>(.*?)</script>', h, re.I|re.S)
    types_found = set()
    breadcrumb_names = None
    for jl in jsonlds:
        try:
            data = json.loads(jl)
        except Exception as e:
            continue
        nodes = []
        if isinstance(data, list):
            nodes = data
        elif isinstance(data, dict):
            if '@graph' in data:
                nodes = data['@graph']
            else:
                nodes = [data]
        for d in nodes:
            if not isinstance(d, dict): continue
            t = d.get('@type')
            if isinstance(t, list):
                for tt in t: types_found.add(tt)
            elif t:
                types_found.add(t)
            if t == 'BreadcrumbList':
                items = sorted(d.get('itemListElement',[]), key=lambda x: x.get('position',0))
                breadcrumb_names = [(it.get('position'), it.get('name')) for it in items]
    return types_found, breadcrumb_names

results = {}
for slug in slugs:
    with open(f'{slug}.html', encoding='utf-8', errors='replace') as f:
        h = f.read()
    types_found, bc = extract_types_and_breadcrumb(h)
    results[slug] = (types_found, bc)
    print(slug, sorted(types_found))
    print("  breadcrumb:", bc)
PYEOF
cat analysis2.txt

